  always @(posedge clk_ctl or negedge bridge_rst_n) if(!bridge_rst_n) sq<=2'd0; else sq<=(sq==2'd2)?2'd0:sq+2'd1;
  reg [161:0] slot [0:3];
  always @(posedge pg_clk) slot[sp] <= {inj_rd, inj_addr};
  wire [1:0] rs = ((sq==2'd1)?2'd0:(sq==2'd2)?2'd1:2'd3) + ((MUT==8)?2'd1:2'd0);
  wire [161:0] ij = slot[rs];
  reg [3:0] v; reg [35:0] row; reg bad; integer k,gg;
  always @* begin
   v=0; row=0; bad=0;
   for(k=0;k<4;k=k+1) begin : dec
    reg [39:0] a, lo; reg on; reg [1:0] grp;
    a = ij[40*k+:40]; lo = ij[80*(k/2)+:40];
    on = ij[160+(k/2)] && !(B39_NOOP!=0 && lo[39] && MUT!=9) && a[5:4]==2'(G);
    grp = {a[6],a[3]};
    if(on) begin
     if(v[grp] && row[9*grp+:9]!=a[15:7]) bad=1'b1;
     v[grp]=1'b1; row[9*grp+:9]=a[15:7];
    end
   end
  end
  assign ij_v=v; assign ij_row=row; assign ij_bad=bad;
 end else begin:g_no_inj
  assign ij_v=4'd0; assign ij_row=36'd0; assign ij_bad=1'b0;
 end
 // ------------------------------------------------------------------ store banks
 wire [32*192-1:0] bank_q;
 wire [31:0] st_inj_drain;
 wire [31:0] st_conflict,st_id_fault;
 // drain store-group reads: port h reads group (h, grp_hi) = slice lanes 8h + 16*grp_hi .. +7
 wire [1:0] dr_v,dr_hi; wire [8:0] dr_row [0:1];
 for(genvar h=0;h<2;h=h+1)begin:g_dr
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign dr_v[h]=w[38]&&!w[37]; assign dr_hi[h]=w[36]; assign dr_row[h]=w[32:24];
 end
 for(genvar n=0;n<32;n=n+1)begin:g_bank
  localparam integer L=lid(n),H=(n/8)%2,HI=n/16,K=n%8;
  wire [53:0] ra; wire [5:0] rv; wire [191:0] q;
  for(genvar p=0;p<4;p=p+1)begin:g_read
   wire [23:0] a=rd_addr[(n*4+p)*24+:24];
   assign ra[p*9+:9]={a[17:16],a[13:7]}; assign rv[p]=rd_re[n*4+p]&&rd_src[n*8+2*p+:2]==2'd0;
  end
  assign ra[4*9+:9]={vi_addr[n*24+16+:2],vi_addr[n*24+7+:7]}; assign rv[4]=vi_re[n]; assign vi_q[n*32+:32]=q[4*32+:32];
  wire drn=dr_v[H]&&dr_hi[H]==1'(HI);
  wire ijn=ij_v[2*HI+H];
  assign ra[5*9+:9]=ijn?ij_row[9*(2*HI+H)+:9]:dr_row[H]; assign rv[5]=drn||ijn;
  assign st_inj_drain[n]=drn&&ijn;
  assign bank_q[n*192+:192]=q;
  assign inj_q[n*32+:32]=q[5*32+:32];
  wire lw=vm_we[n]|kv_we[n];
  wire [23:0] la=vm_we[n]?vm_waddr[n*24+:24]:kv_waddr[n*24+:24];
  wire [31:0] ldat=vm_we[n]?vm_wdata[n*32+:32]:kv_wdata[n*32+:32];
  wire fw=fr_v[H]&&fr_hi[H]==1'(HI);
  wire dwn=(COLLPORT!=0)&&dw_v[HI];
  wire [8:0] dwr=dw_row[9*HI+:9];
  wire [31:0] dwd=dw_d[512*HI+32*((MUT==10)?15-(n%16):(n%16))+:32];
  assign st_conflict[n]=(fw&&lw)||(fw&&dwn)||(dwn&&lw);
  reg idf; integer p2;
  always @*begin
   idf=lw&&(la[6:0]!=7'(L)||la[15:14]!=2'(QID));
   for(p2=0;p2<4;p2=p2+1)if(rv[p2]&&(rd_addr[(n*4+p2)*24+:7]!=7'(L)||rd_addr[(n*4+p2)*24+14+:2]!=2'(QID)))idf=1;
  end
  assign st_id_fault[n]=idf;
  ot_hbm_su_static_pinned_bank #(.READERS(6),.RB(9)) u_bank(.clk(clk_bank[n]),.clk_rd(clk_bank[n]),.clk_ws(clk_bank[n]),.clk_macro(clk_bank_macro[n*6+:6]),.rst_n(rst_n),.read_v(rv),.read_addr(ra),
   .read_data(q),.read_return(),.write_v(lw|fw|dwn),.write_addr(fw?fr_row[H]:dwn?dwr:{la[17:16],la[13:7]}),
   .write_data(fw?fr_dat[H][K*32+:32]:dwn?dwd:ldat));
 end
 // ------------------------------------------------------------------ RF broadcast into lane operands
 wire [4*32-1:0] rf_bword_u; wire [4*9-1:0] rf_bcmd_u; wire [255:0] rf_dsec_u;   // as used (local copy or pins)
 if(RF_LOCAL)begin:g_rf_local
  // local copy beside the bank group: data words without reset; command valids reset (fault checks stay clean)
  reg [4*32-1:0] rf_bword_l; reg [255:0] rf_dsec_l; reg [4*8-1:0] rf_badr_l; reg [3:0] rf_bv_l; integer vb;
  always @(posedge clk_ctl)begin
   rf_bword_l<=rf_bword; rf_dsec_l<=rf_dsec;
   for(vb=0;vb<4;vb=vb+1)rf_badr_l[vb*8+:8]<=rf_bcmd[vb*9+:8];
  end
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)rf_bv_l<=4'd0;
   else for(vb=0;vb<4;vb=vb+1)rf_bv_l[vb]<=rf_bcmd[vb*9+8];
  wire [4*9-1:0] rf_bcmd_l={rf_bv_l[3],rf_badr_l[24+:8],rf_bv_l[2],rf_badr_l[16+:8],rf_bv_l[1],rf_badr_l[8+:8],rf_bv_l[0],rf_badr_l[0+:8]};
  assign rf_bword_u=rf_bword_l; assign rf_bcmd_u=rf_bcmd_l; assign rf_dsec_u=rf_dsec_l;
 end else begin:g_rf_direct
  assign rf_bword_u=rf_bword; assign rf_bcmd_u=rf_bcmd; assign rf_dsec_u=rf_dsec;
 end
 reg [31:0] rf_src_bad;
 for(genvar n=0;n<32;n=n+1)begin:g_opmux
  wire [3:0] is_rf;
  reg [3:0] src1_a,src1_b,src1_c;      // the stream's source code 1 rides the read: request n -> select held n+2..n+3
  for(genvar p=0;p<4;p=p+1)begin:g_p
   assign is_rf[p]=rd_re[n*4+p]&&rd_src[n*8+2*p+:2]==2'd1;
   assign rd_q[(n*4+p)*32+:32]=((MUT==4)?src1_b[p]:src1_c[p])?rf_bword_u[p*32+:32]:bank_q[n*192+p*32+:32];
  end
  always @(posedge clk_lane[n*8])begin src1_a<=is_rf;src1_b<=src1_a;src1_c<=src1_b;end
  integer p2;
  always @*begin
   rf_src_bad[n]=0;
   for(p2=0;p2<4;p2=p2+1)begin
    if(rd_re[n*4+p2]&&rd_src[n*8+2*p2+1])rf_src_bad[n]=1;
    if(is_rf[p2]&&(!rf_bcmd_u[p2*9+8]||rd_addr[(n*4+p2)*24+:24]!={16'd0,rf_bcmd_u[p2*9+:8]}))rf_src_bad[n]=1;
   end
  end
 end
 // ------------------------------------------------------------------ DRAIN: delay line + registered 2:1 group select
 reg [26:0] dd [0:1][0:2];           // {v, src, grp_hi, sector16, mask8}
 wire [1:0] rf_drain_bad;
 for(genvar h=0;h<2;h=h+1)begin:g_drain
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign rf_drain_bad[h]=w[38]&&w[37]&&!(G==0&&h==0);
  integer k;
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)begin for(k=0;k<3;k=k+1)dd[h][k]<=27'd0; end
   else begin dd[h][0]<={w[38],w[37],w[36],w[23:0]};dd[h][1]<=dd[h][0];dd[h][2]<=dd[h][1]; end
  wire hi=dd[h][2][24]^((MUT==2)?1'b1:1'b0);
  reg [255:0] sel; integer kk;
  always @*begin
   for(kk=0;kk<8;kk=kk+1)sel[kk*32+:32]=bank_q[(8*h+16*hi+kk)*192+5*32+:32];
   if(dd[h][2][25])sel=rf_dsec_u;
  end
  reg wq_v; reg [279:0] wq_p;
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)wq_v<=1'b0; else wq_v<=dd[h][2][26];
  always @(posedge clk_ctl)wq_p<={dd[h][2][23:8],sel,dd[h][2][7:0]};
  assign su_wq[h*281+:281]={wq_v,wq_p};
 end
 // ------------------------------------------------------------------ reducer operand stage
 // red_sel = {v[11], op[10:8], osel[7], lane[6:0]}; lane L is in this slice iff (L mod 64) / 16 == G
 wire [6:0] rl=red_sel[6:0];
 wire mine=red_sel[11]&&!red_sel[7]&&(rl[5:4]==2'(G));
 wire [4:0] rn={rl[6],rl[3:0]};
 wire ext=red_sel[10:8]==3'd0||red_sel[10:8]==3'd1||red_sel[10:8]==3'd3;
 wire red_bad=mine&&ext&&!ro_v[rn];
 always @(posedge clk_ctl)slice_x<=ro_x[rn*32+:32];
 // ------------------------------------------------------------------ PRETREE: reducer ingress widening
 wire pt_fault;
 if(PRETREE!=0)begin:g_pretree
  ot_hbm_su_red_pretree_s #(.LAT(6)) u_pt(.clk(clk_ctl),.rst_n(rst_n),.tree_cmd(tree_cmd),.ro_x(ro_x),.ro_v(ro_v),
   .tree_o(tree_o),.fault(pt_fault));
 end else begin:g_no_pretree
  assign tree_o=67'd0; assign pt_fault=1'b0;
 end
 // ------------------------------------------------------------------ sticky fault
 always @(posedge clk_ctl or negedge rst_n)
  if(!rst_n)fault<=1'b0;
  else if((|l_fault)||(|l_coll)||(|leaf_fault)||(|bridge_fault)||(|st_conflict)||(|st_id_fault)||(|cmd_far)||(|rf_src_bad)||
          (|rf_drain_bad)||red_bad||side_fault||(|st_inj_drain)||ij_bad||pt_fault)fault<=1'b1;
endmodule
`default_nettype wire
